import{_ as r,C as i,o as a,c as h,j as e,a as o,E as s,a2 as l}from"./chunks/framework.TaNiW7i8.js";const w=JSON.parse('{"title":"Sync","description":"","frontmatter":{"title":"Sync"},"headers":[],"relativePath":"en/guide/sync.md","filePath":"en/guide/sync.md"}'),c={name:"en/guide/sync.md"};function g(u,t,d,m,y,p){const n=i("Capture");return a(),h("div",null,[t[0]||(t[0]=e("h1",{id:"sync",tabindex:"-1"},[o("Sync "),e("a",{class:"header-anchor",href:"#sync","aria-label":'Permalink to "Sync"'},"​")],-1)),t[1]||(t[1]=e("p",null,"Your memory is an ordinary git repository. Kessho syncs it, with the git installed on your computer, to the remote you choose, and never forces anything. An indicator also tells you when the memory has just changed.",-1)),s(n,{name:"synchro",alt:"Memory synchronization: files changed since the last commit and a commit message being typed."}),t[2]||(t[2]=l('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Syncing is driven from two places: the status bar, for one click, and <a href="/Kessho/en/guide/settings.html">Settings</a> &gt; <strong>Sync</strong>, for the detail.</p><ul><li><strong>In the status bar</strong>, at the bottom of the window: <ul><li>the <strong>Sync the memory</strong> button, far left (tooltip: &quot;Sync: commit, pull, push&quot;);</li><li>the <strong>git</strong> field, which tells you where the repository stands: <strong>up to date</strong>, <strong>N to push</strong>, <strong>N to pull</strong>, <strong>N uncommitted</strong>, <strong>conflict</strong> or <strong>operation in progress</strong>. The tooltip gives the full state line.</li></ul></li><li><strong>In Settings &gt; Sync</strong>: <ul><li><strong>The state line</strong>: the branch and what it tracks, then how far behind and ahead it is, for example &quot;main → origin/main · 2 to push · 0 to pull · remote checked 10:30&quot;. The time is when the remote was last checked.</li><li><strong>The three actions</strong>: <strong>Sync</strong>, <strong>Pull</strong>, <strong>Push</strong>.</li><li><strong>Changes</strong>: the number of modified, deleted and untracked files (&quot;3 modified · 0 deleted · 1 untracked&quot;), the <strong>Show the list</strong> disclosure, the <strong>Commit message</strong> field and the <strong>Commit the changes</strong> button.</li><li><strong>Remote</strong>: the address of the remote repository, and the <strong>Remote URL (https or ssh)</strong> field.</li><li><strong>Automation</strong>: the &quot;Agents commit and sync automatically&quot; checkbox.</li><li><strong>Warnings</strong>, when there is something to say.</li></ul></li><li><strong>The freshness indicator</strong>, top right, next to your avatar: a dot that lights up when the memory changes.</li></ul><p>If the memory is not a repository yet, the section says: &quot;This memory is not a git repository. Initialising it creates no commit and connects no remote.&quot; If git is not installed, it shows &quot;git not found&quot; with the command to install it. The rest of Kessho works without git.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="sync-in-one-click" tabindex="-1">Sync in one click <a class="header-anchor" href="#sync-in-one-click" aria-label="Permalink to &quot;Sync in one click&quot;">​</a></h3><p>Click <strong>Sync the memory</strong> in the status bar. Kessho does three things, in this order:</p><ol><li>it commits what changed, under the message &quot;vault backup: YYYY-MM-DD HH:mm:ss&quot; (nothing is committed if there is nothing new);</li><li>it pulls what is new on the remote;</li><li>it pushes your commits.</li></ol><p>Nothing is stashed and nothing is forced. When it finishes, the <strong>git</strong> field updates; a screen reader hears &quot;Memory synced.&quot;.</p><p>If something blocks it, the bar shows &quot;failed:&quot; followed by one word (<strong>conflict</strong>, <strong>offline</strong>, <strong>authentication</strong>, <strong>dirty tree</strong>, <strong>busy</strong>, <strong>timeout</strong>, <strong>identity</strong>, <strong>markers</strong>). Hover it to read the full reason. If the backup commit happened before the failure, the message says so: it was made locally.</p><p>The button is greyed out, with the reason in its tooltip, when no remote is connected (&quot;No remote: connect one below.&quot;) or a git operation is already running.</p><h3 id="commit-your-changes-by-hand" tabindex="-1">Commit your changes by hand <a class="header-anchor" href="#commit-your-changes-by-hand" aria-label="Permalink to &quot;Commit your changes by hand&quot;">​</a></h3><p>In <strong>Changes</strong>:</p><ol><li>Click <strong>Show the list</strong> to read the files involved.</li><li>Write a <strong>Commit message</strong>.</li><li>Click <strong>Commit the changes</strong>, then <strong>Confirm</strong> at the question &quot;Commit N changes with this message?&quot;. <strong>Cancel</strong> drops it.</li></ol><p>The button stays greyed out while the message is empty. The message cannot exceed 1,000 characters. Your commit name and email must be filled in your profile (the circle with your initial, top right).</p><h3 id="pull-or-push" tabindex="-1">Pull or push <a class="header-anchor" href="#pull-or-push" aria-label="Permalink to &quot;Pull or push&quot;">​</a></h3><ul><li><strong>Pull</strong> fetches what is new on the remote and applies it. It is greyed out while changes are uncommitted: &quot;Uncommitted changes prevent pulling: commit them first.&quot;</li><li><strong>Push</strong> sends your commits. It is greyed out when there is nothing to push.</li><li><strong>Sync</strong> pulls, then pushes.</li></ul><p>Kessho never pulls on its own: the state line shows &quot;N to pull&quot;, and you decide.</p><h3 id="connect-a-remote" tabindex="-1">Connect a remote <a class="header-anchor" href="#connect-a-remote" aria-label="Permalink to &quot;Connect a remote&quot;">​</a></h3><p>In <strong>Remote</strong>, paste the repository&#39;s address into <strong>Remote URL (https or ssh)</strong> and click <strong>Connect</strong> (the button reads <strong>Change</strong> once a remote is connected). The accepted forms are <code>https://host/path</code>, <code>ssh://host/path</code> and <code>user@host:path</code>.</p><p>No credential is stored: Kessho uses your system&#39;s own. An address that carries one is refused.</p><h3 id="initialise-the-repository" tabindex="-1">Initialise the repository <a class="header-anchor" href="#initialise-the-repository" aria-label="Permalink to &quot;Initialise the repository&quot;">​</a></h3><p>If your memory is not a repository yet, click <strong>Initialise the repository</strong>. It creates no commit and connects no remote.</p><h3 id="let-your-agents-sync" tabindex="-1">Let your agents sync <a class="header-anchor" href="#let-your-agents-sync" aria-label="Permalink to &quot;Let your agents sync&quot;">​</a></h3><p>The <strong>Automation</strong> checkbox (&quot;Agents commit and sync automatically&quot;) is ticked by default. When it is ticked, each tool of your AI agents that writes to the memory commits only what it touched, then pushes. Your uncommitted changes never leave with it. Untick the box to take control back.</p><p>To ask an agent to sync, see <a href="/Kessho/en/agent/synchroniser.html">Sync the memory</a>. The matching tools are described in the <a href="/Kessho/en/reference/mcp/git.html">MCP reference</a>.</p><h3 id="understand-a-refusal" tabindex="-1">Understand a refusal <a class="header-anchor" href="#understand-a-refusal" aria-label="Permalink to &quot;Understand a refusal&quot;">​</a></h3><p>The messages say what to do. The most common ones:</p><ul><li><strong>Conflict</strong>: the pull is cancelled and nothing changed. The files involved are named: merge them by hand, commit, then sync.</li><li><strong>Push refused</strong>: the remote moved ahead. Pull first. Nothing is ever forced.</li><li><strong>Offline</strong>: the remote cannot be reached. Nothing changed, try again later.</li><li><strong>Authentication refused</strong>: Kessho uses your system&#39;s credentials. For GitHub over https, run &quot;gh auth login&quot;; otherwise switch the remote to SSH.</li><li><strong>Operation in progress</strong> or <strong>repository busy</strong>: another git process is working on the memory. Wait a moment.</li></ul><p>Under <strong>Warnings</strong>, Kessho also tells you when conflict markers have been committed in a file, when it resumed an interrupted operation, or when the Obsidian Git plugin is syncing the same memory (two automations get in each other&#39;s way: set its intervals to 0). Kessho never changes Obsidian&#39;s configuration.</p><h3 id="know-when-the-memory-changed" tabindex="-1">Know when the memory changed <a class="header-anchor" href="#know-when-the-memory-changed" aria-label="Permalink to &quot;Know when the memory changed&quot;">​</a></h3><p>The freshness indicator, top right, lights up when the memory changes, for example when an agent has just written. Click it to open its panel.</p>',32)),s(n,{name:"fraicheur",alt:"The freshness indicator, top right: an agent has just written in the Procedures zone, the indicator lights up and says what moved."}),t[3]||(t[3]=e("ul",null,[e("li",null,'The first line says since when: "Seen a second ago." With no change since opening: "No change since opening." If the reading fails: "The memory state could not be read."'),e("li",null,[e("strong",null,"Changes since the last reload"),o(` lists the zones that moved, with the number of changes: "Procedures 1". The number counts changes, not the zone's size: adding a note then removing it makes two.`)]),e("li",null,'When a note changed without any zone changing size, the panel says so: "A note changed, without any zone changing size."'),e("li",null,[e("strong",null,"Reload"),o(" refreshes what the screen shows and resets the count.")])],-1))])}const b=r(c,[["render",g]]);export{w as __pageData,b as default};
